{"results": [{"id": "hp_doc_1b303fc12eb41e2051a9f65a9bd31197175728bdd5b2353ee02518bb2e210c7e", "title": "Stinson Lake, New Hampshire", "text": "Stinson Lake is an unincorporated community in the town of Rumney in Grafton County, New Hampshire, United States. It is located at the south end of Stinson Lake, around the lake's outlet. The village is 4 mi north of the village of Rumney, via Stinson Lake Road.", "score": 43.1456}, {"id": "hp_doc_7c2403113dc12d121f8739253c9b474f20328ad206ee89ec9cd81a37120c3925", "title": "Stinson Lake", "text": "Stinson Lake is a 342 acre water body located in the town of Rumney in Grafton County, New Hampshire, United States. The lake is in the southern part of the White Mountains and is the largest lake in the White Mountain National Forest. Water from Stinson Lake flows via Stinson Brook, the Baker River, and the Pemigewasset River to the Merrimack River.", "score": 42.1349}, {"id": "hp_doc_831c28b360e44312751142506b1933867143cddca7ba309e30873cfba9017a9b", "title": "Stone Lake (CDP), Wisconsin", "text": "Stone Lake is an unincorporated census-designated place in Sawyer and Washburn counties, Wisconsin, United States. Stone Lake is located on the eastern shore of Stone Lake and along Wisconsin Highway 70, 12 mi west-northwest of Couderay. The Sawyer County portion of the community is located in the town of Sand Lake, while the Washburn County portion is located in the town of Stone Lake. As of the 2010 census, its population is 178.", "score": 35.3175}], "remaining_searches": 2}
